using System;
using System.Collections.Generic;
using System.Linq;

namespace LargestNumber {
    class Program {
        static bool ChkDec(int num) {
            HashSet<int> set = new HashSet<int>();

            return num.ToString()
                .Select(c => c - '0')
                .All(d => (d != 0) && (num % d == 0) && set.Add(d));
        }

         static void Main() {
            int result = Enumerable.Range(0, 98764321)
                .Reverse()
                .Where(ChkDec)
                .First();
            Console.WriteLine(result);
        }
    }
}

using System;

class Program
{
    static string Reverse(string value)
    {
        char[] chars = value.ToCharArray();
        Array.Reverse(chars);
        return new string(chars);
    }

    static bool IsPalindrome(string value)
    {
        return value == Reverse(value);
    }

    static void Main(string[] args)
    {
        ConFsole.WriteLine(IsPalindrome("ingirumimusnocteetconsumimurigni"));
    }
}

using System;

public class ReverseWordsInString
{
    public static void Main(string[] args)
    {
        string text = @"ice and fire";

         foreach (string line in text.Split(Environment.NewLine)) {
            //Splits on any whitespace, not just spaces

            string[] words = line.Split(default(char[]), RemoveEmptyEntries);
            Array.Reverse(words);
            WriteLine(string.Join(" ", words));
        }
    }
}

